"""Sum the first N cubes of natural numbers.

    >>> sum_cubes(5)
    225
    """
def sum_cubes(n: Any) -> object {
    (total, k) = (0, 1);
    while (k <= n) {
        (total, k) = ((total + pow(k, 3)), (k + 1));
    }
    return total;
}

test_blocks:
test "t0" {
    assert (sum_cubes(1) == 1);;
}

test "t1" {
    assert (sum_cubes(5) == 225);;
}

test "t2" {
    assert (sum_cubes(-2) == 0);;
}

test "t3" {
    assert (sum_cubes(0) == 0);;
}

test "t4" {
    assert (sum_cubes(10) == 3025);;
}
